<script setup lang="ts">
import { computed,onBeforeUnmount,onMounted,ref } from 'vue';import { useRouter } from 'vue-router';import { AlertTriangle,ArrowUpRight,Building2,Camera,ChevronRight,Construction,HardHat,RadioTower,ShieldCheck,Video,Wifi } from 'lucide-vue-next';import BarChart from '@/charts/BarChart.vue';import DonutChart from '@/charts/DonutChart.vue';import ResourceState from '@/components/common/ResourceState.vue';import ProjectMap from '@/components/project/ProjectMap.vue';import { getProjectList,type ProjectRecord } from '@/api/project';import { getCameraPage,type CameraRecord } from '@/api/camera';import { getDeviceRecords,type DeviceRecordRaw } from '@/api/device';import { getAlarms,type AlarmRecordRaw } from '@/api/alarm';
const router=useRouter(),projects=ref<ProjectRecord[]>([]),cameras=ref<CameraRecord[]>([]),devices=ref<DeviceRecordRaw[]>([]),alarms=ref<AlarmRecordRaw[]>([]),loading=ref(false),error=ref('');let timer:number|undefined
const load=async(silent=false)=>{if(!silent)loading.value=true;error.value='';try{const [p,c,d,a]=await Promise.all([getProjectList(),getCameraPage(1,200),getDeviceRecords(),getAlarms()]);projects.value=p.data;cameras.value=c.data.records;devices.value=d.data;alarms.value=a.data}catch(e){error.value=e instanceof Error?e.message:'网络异常'}finally{loading.value=false}}
const activeProjects=computed(()=>projects.value.filter(x=>x.projectStatus==='UNDER_CONSTRUCTION').length);const onlineDevices=computed(()=>devices.value.filter(x=>x.status==='ONLINE').length);const pendingAlarms=computed(()=>alarms.value.filter(x=>['PENDING','HANDLING'].includes(x.alarmStatus)).length);const onlineCameras=computed(()=>cameras.value.filter(x=>x.status===1).length);const deviceOnlineRate=computed(()=>devices.value.length?Math.round(onlineDevices.value/devices.value.length*100):0);const cameraOnlineRate=computed(()=>cameras.value.length?Math.round(onlineCameras.value/cameras.value.length*100):0);const safetyScore=computed(()=>Math.max(60,100-pendingAlarms.value*3));const deviceTypes=computed(()=>{const m=new Map<string,number>();devices.value.forEach(x=>m.set(x.deviceType,(m.get(x.deviceType)||0)+1));return [...m.entries()]});const latestAlarms=computed(()=>alarms.value.slice(0,5));const priorityProject=computed(()=>projects.value.find(x=>x.projectStatus==='UNDER_CONSTRUCTION')||projects.value[0]);const kpis=computed(()=>[{label:'在建项目',value:activeProjects.value,total:`全部 ${projects.value.length}`,icon:Building2,tone:'blue',path:'/projects'},{label:'在线设备',value:onlineDevices.value,total:`在线率 ${deviceOnlineRate.value}%`,icon:Construction,tone:'cyan',path:'/equipment'},{label:'在线摄像头',value:onlineCameras.value,total:`在线率 ${cameraOnlineRate.value}%`,icon:Camera,tone:'green',path:'/cameras'},{label:'待处置报警',value:pendingAlarms.value,total:pendingAlarms.value?'需要关注':'当前平稳',icon:AlertTriangle,tone:pendingAlarms.value?'red':'green',path:'/alarms'}]);const quickActions=[{label:'项目档案',desc:'进度与参建单位',icon:Building2,path:'/projects'},{label:'塔吊监测',desc:'载荷与力矩',icon:RadioTower,path:'/tower-monitor'},{label:'视频巡查',desc:'实时监控画面',icon:Video,path:'/video'},{label:'基坑安全',desc:'风险与监测点',icon:HardHat,path:'/foundation-pits'}];onMounted(()=>{void load();timer=window.setInterval(()=>void load(true),30000)});onBeforeUnmount(()=>window.clearInterval(timer))
</script>
<template><ResourceState :loading="loading" :error="error" :empty="false" @retry="load"><div class="command-strip"><div class="command-copy"><span class="command-badge"><i/>安全态势实时感知</span><h2>城市建设运行指挥中心</h2><p>聚合项目进度、设备运行、视频巡查与报警处置，形成一屏统览的监管工作台。</p><div class="command-meta"><span>平台安全指数 <b>{{ safetyScore }}</b></span><span>设备在线率 <b>{{ deviceOnlineRate }}%</b></span><span>数据刷新 <b>30s</b></span></div></div><div class="command-score"><div class="score-orbit" :style="{ '--score': `${safetyScore}%` }"><span><b>{{ safetyScore }}</b><small>综合安全分</small></span></div><div><strong>{{ pendingAlarms?'存在待处置风险':'整体运行平稳' }}</strong><small>{{ pendingAlarms }} 条报警待跟进</small><button @click="router.push('/alarms')">进入处置中心 <ChevronRight :size="13"/></button></div></div></div>
<div class="kpi-grid"><button v-for="item in kpis" :key="item.label" class="tech-panel kpi-card" :class="`tone-${item.tone}`" @click="router.push(item.path)"><span class="kpi-icon"><component :is="item.icon"/></span><span class="kpi-copy"><small>{{ item.label }}</small><strong>{{ item.value }}</strong><em>{{ item.total }}</em></span><ArrowUpRight class="kpi-arrow" :size="16"/></button></div>
<div class="dashboard-focus"><article class="tech-panel map-card"><div class="panel-head"><div><h2 class="panel-title">项目空间态势</h2><small class="head-note">{{ priorityProject?.projectName||'暂无在建项目' }}</small></div><button class="text-link" @click="router.push('/projects')">项目管理 <ChevronRight :size="13"/></button></div><ProjectMap :name="priorityProject?.projectName" :longitude="priorityProject?.longitude" :latitude="priorityProject?.latitude"/><div class="map-footer"><span><i class="blue"/>项目 {{ projects.length }}</span><span><i class="green"/>设备 {{ devices.length }}</span><span><i class="cyan"/>视频 {{ cameras.length }}</span><span><i class="red"/>报警 {{ pendingAlarms }}</span></div></article>
<article class="tech-panel alarm-card"><div class="panel-head"><div><h2 class="panel-title">风险事件</h2><small class="head-note">按发生时间排序</small></div><span class="alarm-count">{{ pendingAlarms }}</span></div><div class="alarm-stream"><button v-for="row in latestAlarms" :key="row.id" @click="router.push({path:'/alarms',query:{deviceId:row.deviceId}})"><span class="alarm-mark" :class="row.alarmLevel"><AlertTriangle :size="14"/></span><span class="alarm-copy"><b>{{ row.alarmTitle }}</b><small>{{ row.triggeredAt }} · 设备 {{ row.deviceId }}</small></span><span class="alarm-state">{{ row.alarmStatus }}</span></button><div v-if="!latestAlarms.length" class="calm-state"><ShieldCheck :size="28"/><b>暂无风险事件</b><span>当前监测范围运行平稳</span></div></div><button class="alarm-more" @click="router.push('/alarms')">查看全部报警记录 <ChevronRight :size="13"/></button></article></div>
<div class="dashboard-bottom"><article class="tech-panel"><div class="panel-head"><h2 class="panel-title">项目施工进度</h2><span class="panel-meta">TOP 6</span></div><div class="chart"><BarChart :labels="projects.slice(0,6).map(x=>x.projectName)" :values="projects.slice(0,6).map(x=>Number(x.progressPercent||0))"/></div></article><article class="tech-panel"><div class="panel-head"><h2 class="panel-title">设备类型分布</h2><span class="panel-meta">{{ devices.length }} 台</span></div><div class="chart"><DonutChart :data="deviceTypes.map(([name,value])=>({name,value}))" :center-text="String(devices.length)" center-subtext="设备总数"/></div></article><article class="tech-panel quick-card"><div class="panel-head"><h2 class="panel-title">快捷工作台</h2><span class="panel-meta">常用功能</span></div><div class="quick-grid"><button v-for="item in quickActions" :key="item.path" @click="router.push(item.path)"><span><component :is="item.icon" :size="18"/></span><div><b>{{ item.label }}</b><small>{{ item.desc }}</small></div><ChevronRight :size="14"/></button></div></article></div></ResourceState></template>
<style scoped>.command-strip{position:relative;display:grid;grid-template-columns:1fr 410px;min-height:190px;margin-bottom:12px;overflow:hidden;border:1px solid rgba(58,162,245,.24);border-radius:12px;background:radial-gradient(circle at 78% 30%,rgba(22,119,255,.25),transparent 33%),linear-gradient(120deg,rgba(13,54,91,.96),rgba(6,28,52,.9));box-shadow:0 18px 55px rgba(0,7,20,.25)}.command-strip:after{position:absolute;inset:0;content:'';pointer-events:none;background:linear-gradient(90deg,transparent 49%,rgba(56,166,238,.04) 50%,transparent 51%);background-size:36px 100%}.command-copy{position:relative;z-index:1;padding:25px 30px}.command-badge{display:inline-flex;align-items:center;gap:7px;color:#55c5ff;font-size:9px;letter-spacing:.12em}.command-badge i{width:6px;height:6px;border-radius:50%;background:#36d399;box-shadow:0 0 9px #36d399}.command-copy h2{margin:12px 0 8px;color:#f0f7ff;font-size:26px;letter-spacing:.04em}.command-copy p{max-width:680px;margin:0;color:#7f9db7;font-size:11px}.command-meta{display:flex;gap:23px;margin-top:20px}.command-meta span{color:#6385a2;font-size:9px}.command-meta b{margin-left:5px;color:#bfe1f8;font-size:11px}.command-score{position:relative;z-index:1;display:flex;align-items:center;gap:20px;padding:20px 28px;border-left:1px solid rgba(79,168,255,.1)}.score-orbit{position:relative;display:grid;place-items:center;width:116px;height:116px;border-radius:50%;background:conic-gradient(#37d3a0 0 var(--score,89%),rgba(75,124,165,.13) 0)}.score-orbit:before{position:absolute;inset:8px;border-radius:50%;content:'';background:#0a2642}.score-orbit span{position:relative;display:grid;text-align:center}.score-orbit b{color:#eaf7ff;font-size:29px}.score-orbit small{color:#5fa88e;font-size:8px}.command-score>div:last-child{display:grid;gap:6px}.command-score strong{color:#ddecf8;font-size:13px}.command-score small{color:#6d8ba6;font-size:9px}.command-score button{display:flex;align-items:center;gap:4px;margin-top:8px;padding:0;border:0;color:#4bbcff;background:transparent;font-size:9px;cursor:pointer}.kpi-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:12px}.kpi-card{display:grid;grid-template-columns:48px 1fr 18px;align-items:center;gap:11px;min-height:104px;padding:15px;color:#4caeff;cursor:pointer;text-align:left;transition:.2s}.kpi-card:hover{transform:translateY(-2px);border-color:currentColor}.kpi-icon{display:grid;place-items:center;width:46px;height:46px;border-radius:9px;background:rgba(22,119,255,.12)}.kpi-copy{display:grid}.kpi-copy small{color:#7897b2;font-size:10px}.kpi-copy strong{margin-top:3px;color:#edf7ff;font-size:27px}.kpi-copy em{color:#5f7f9b;font-size:8px;font-style:normal}.kpi-arrow{align-self:start;color:#37698f}.tone-green{color:#36d399}.tone-cyan{color:#22d3ee}.tone-red{color:#ff6478}.dashboard-focus{display:grid;grid-template-columns:minmax(560px,1.45fr) minmax(330px,.7fr);gap:12px}.panel-head>div{display:grid;gap:2px}.head-note{color:#557794;font-size:8px}.map-card :deep(.project-map){height:370px;border:0;border-radius:0}.map-footer{display:flex;align-items:center;gap:18px;min-height:42px;padding:0 14px;border-top:1px solid rgba(79,168,255,.09);color:#6585a1;font-size:8px}.map-footer i{display:inline-block;width:6px;height:6px;margin-right:4px;border-radius:50%}.blue{background:#278cff}.green{background:#36d399}.cyan{background:#22d3ee}.red{background:#ff6478}.alarm-card{display:flex;min-height:458px;flex-direction:column}.alarm-count{display:grid;place-items:center;min-width:26px;height:22px;border-radius:11px;color:#ff7283;background:rgba(255,94,114,.12);font-size:10px}.alarm-stream{flex:1;padding:5px 12px}.alarm-stream>button{display:grid;grid-template-columns:31px 1fr auto;align-items:center;gap:9px;width:100%;min-height:67px;padding:8px 2px;border:0;border-bottom:1px solid rgba(79,168,255,.08);background:transparent;text-align:left;cursor:pointer}.alarm-stream>button:hover{background:rgba(22,119,255,.06)}.alarm-mark{display:grid;place-items:center;width:30px;height:30px;border-radius:6px;color:#ffad43;background:rgba(255,159,67,.1)}.alarm-mark.HIGH,.alarm-mark.CRITICAL{color:#ff6478;background:rgba(255,94,114,.11)}.alarm-copy{display:grid;gap:5px}.alarm-copy b{overflow:hidden;color:#cddfeb;font-size:10px;text-overflow:ellipsis;white-space:nowrap}.alarm-copy small{color:#557592;font-size:8px}.alarm-state{padding:3px 5px;border-radius:3px;color:#f6a543;background:rgba(251,191,36,.09);font-size:7px}.alarm-more{display:flex;align-items:center;justify-content:center;gap:4px;min-height:40px;border:0;border-top:1px solid rgba(79,168,255,.09);color:#57b9f3;background:rgba(22,119,255,.04);font-size:9px;cursor:pointer}.calm-state{display:flex;align-items:center;justify-content:center;flex-direction:column;gap:6px;height:100%;color:#36d399}.calm-state b{color:#bcdacf}.calm-state span{color:#607f9a;font-size:8px}.dashboard-bottom{display:grid;grid-template-columns:1.15fr .85fr 1fr;gap:12px;margin-top:12px}.chart{height:270px;padding:6px}.quick-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;padding:12px}.quick-grid button{display:grid;grid-template-columns:35px 1fr 15px;align-items:center;gap:8px;min-height:78px;padding:10px;border:1px solid rgba(79,168,255,.12);border-radius:7px;color:#4eb7f5;background:linear-gradient(135deg,rgba(22,119,255,.09),rgba(9,33,59,.34));text-align:left;cursor:pointer}.quick-grid button:hover{border-color:rgba(79,168,255,.36);background:rgba(22,119,255,.13)}.quick-grid button>span{display:grid;place-items:center;width:34px;height:34px;border-radius:6px;background:rgba(22,119,255,.12)}.quick-grid div{display:grid;gap:4px}.quick-grid b{color:#cfe1ef;font-size:10px}.quick-grid small{color:#5e7e9a;font-size:8px}@media(max-width:1200px){.command-strip{grid-template-columns:1fr 350px}.dashboard-bottom{grid-template-columns:repeat(2,1fr)}.quick-card{grid-column:1/-1}}@media(max-width:900px){.command-strip{grid-template-columns:1fr}.command-score{display:none}.dashboard-focus{grid-template-columns:1fr}.kpi-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:620px){.command-copy{padding:20px}.command-copy h2{font-size:21px}.command-meta{flex-wrap:wrap;gap:10px}.kpi-grid,.dashboard-bottom{grid-template-columns:1fr}.quick-card{grid-column:auto}}</style>
